script:
// Toggle (ds-metrics §5): title (body, el16 / el6 disabled, fills the row) + switch, gap md, min height 44. The iOS DS
// wraps the system switch, so the geometry is Android SwitchPrimary's: 36×20 track (bg4 → accentPrimary), 16pt onAccent
// knob inset 2. Knob and track animate implicitly (@motion.snappy / @motion.fast). `change` carries the new value.
//  • controlled: bind `value` to screen state and assign it in on.change —
//      {"type": "Toggle", "props": {"title": "Push", "value": "=push"}, "on": {"change": "push = event.value"}}
//  • uncontrolled: leave `value` unset — the toggle keeps instance state `local` and reports it in `change`.
param title: string = ""
param value: bool? = null
param enabled: bool = true
event change(value: bool)
state local = false
let isOn = value ?? local

on.tap:
if enabled {
  local = !isOn
  haptic("selection")
  emit change({value: local})
}
